-- UNAPPROVED tracked audit-only ACL reduction. No row/schema/policy/service_role change.
DO $audit_revoke$ DECLARE prior_security jsonb; prior_data text; BEGIN
 if exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid in ('public.save_url_result_draft(uuid,uuid,uuid,integer,jsonb)'::regprocedure,'private.save_url_result_draft_impl(uuid,uuid,uuid,integer,jsonb)'::regprocedure,'public.save_first_result_draft(uuid,uuid,uuid,integer,jsonb)'::regprocedure,'private.save_first_result_draft_impl(uuid,uuid,uuid,integer,jsonb)'::regprocedure) and a.grantee=0 and a.privilege_type='EXECUTE') or exists(select 1 from (values('anon'),('authenticated'),('service_role')) acl_role(name) cross join (values('public.save_url_result_draft(uuid,uuid,uuid,integer,jsonb)'::regprocedure),('private.save_url_result_draft_impl(uuid,uuid,uuid,integer,jsonb)'::regprocedure),('public.save_first_result_draft(uuid,uuid,uuid,integer,jsonb)'::regprocedure),('private.save_first_result_draft_impl(uuid,uuid,uuid,integer,jsonb)'::regprocedure)) f(id) where has_function_privilege(acl_role.name,f.id,'EXECUTE')) then raise exception 'Expected closed effective ACL'; end if;
 if (select count(*) from supabase_migrations.schema_migrations)<>23 then raise exception 'Expected 23 records before audit revoke; reconcile unknown state'; end if;
 if (select coalesce(jsonb_agg(to_jsonb(x) order by grantee,privilege),'[]') from (select case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end grantee,pg_get_userbyid(a.grantor) grantor,a.privilege_type privilege,a.is_grantable grantable from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a where c.oid='public.audit_events'::regclass ) x) is distinct from '[{"grantee":"anon","grantor":"postgres","privilege":"DELETE","grantable":false},{"grantee":"anon","grantor":"postgres","privilege":"INSERT","grantable":false},{"grantee":"anon","grantor":"postgres","privilege":"MAINTAIN","grantable":false},{"grantee":"anon","grantor":"postgres","privilege":"REFERENCES","grantable":false},{"grantee":"anon","grantor":"postgres","privilege":"SELECT","grantable":false},{"grantee":"anon","grantor":"postgres","privilege":"TRIGGER","grantable":false},{"grantee":"anon","grantor":"postgres","privilege":"TRUNCATE","grantable":false},{"grantee":"anon","grantor":"postgres","privilege":"UPDATE","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"DELETE","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"INSERT","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"MAINTAIN","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"REFERENCES","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"SELECT","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"TRIGGER","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"TRUNCATE","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"UPDATE","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"DELETE","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"INSERT","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"MAINTAIN","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"REFERENCES","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"SELECT","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"TRIGGER","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"TRUNCATE","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"UPDATE","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"DELETE","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"INSERT","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"MAINTAIN","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"REFERENCES","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"SELECT","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"TRIGGER","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"TRUNCATE","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"UPDATE","grantable":false}]'::jsonb then raise exception 'Audit raw ACL differs from parent 08:51 baseline'; end if;
 if not exists(select 1 from pg_class where oid='public.audit_events'::regclass and relowner='postgres'::regrole and relrowsecurity and not relforcerowsecurity) then raise exception 'Audit owner/RLS drift'; end if;
 if (select count(*) from pg_policies where schemaname='public' and tablename='audit_events')<>1 or not exists(select 1 from pg_policies where schemaname='public' and tablename='audit_events' and policyname='audit_read_owner' and cmd='SELECT' and roles=array['authenticated']::name[] and qual='private.has_org_role(organization_id, ARRAY[''owner''::text])' and with_check is null) then raise exception 'Audit SELECT policy drift'; end if;
 prior_security:=(select jsonb_build_object('owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'policies',(select jsonb_agg(to_jsonb(p) order by policyname) from pg_policies p where schemaname='public' and tablename='audit_events')) from pg_class c where c.oid='public.audit_events'::regclass); prior_data:=(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text)::text,'[]'),'UTF8')),'hex') from public.audit_events t);
 revoke INSERT,UPDATE,DELETE,TRUNCATE on table public.audit_events from PUBLIC,anon,authenticated;
 if exists(select 1 from (values('anon'),('authenticated')) r(name) where has_table_privilege(r.name,'public.audit_events','INSERT,UPDATE,DELETE,TRUNCATE')) or exists(select 1 from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a where c.oid='public.audit_events'::regclass and a.grantee=0 and a.privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE')) then raise exception 'Audit effective write ACL must be closed'; end if;
 if (select coalesce(jsonb_agg(to_jsonb(x) order by grantee,privilege),'[]') from (select case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end grantee,pg_get_userbyid(a.grantor) grantor,a.privilege_type privilege,a.is_grantable grantable from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a where c.oid='public.audit_events'::regclass ) x) is distinct from '[{"grantee":"anon","grantor":"postgres","privilege":"MAINTAIN","grantable":false},{"grantee":"anon","grantor":"postgres","privilege":"REFERENCES","grantable":false},{"grantee":"anon","grantor":"postgres","privilege":"SELECT","grantable":false},{"grantee":"anon","grantor":"postgres","privilege":"TRIGGER","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"MAINTAIN","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"REFERENCES","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"SELECT","grantable":false},{"grantee":"authenticated","grantor":"postgres","privilege":"TRIGGER","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"DELETE","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"INSERT","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"MAINTAIN","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"REFERENCES","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"SELECT","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"TRIGGER","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"TRUNCATE","grantable":false},{"grantee":"postgres","grantor":"postgres","privilege":"UPDATE","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"DELETE","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"INSERT","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"MAINTAIN","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"REFERENCES","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"SELECT","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"TRIGGER","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"TRUNCATE","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"UPDATE","grantable":false}]'::jsonb or (select jsonb_build_object('owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'policies',(select jsonb_agg(to_jsonb(p) order by policyname) from pg_policies p where schemaname='public' and tablename='audit_events')) from pg_class c where c.oid='public.audit_events'::regclass) is distinct from prior_security or (select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text)::text,'[]'),'UTF8')),'hex') from public.audit_events t) is distinct from prior_data then raise exception 'Audit revoke exceeded exact ACL allowlist'; end if;
END $audit_revoke$;
